function distField(cs, step, pad) {
  const polys = cs.toPolygons(),
    bnd = cs.bounds();
  const x0 = bnd.min[0] - pad,
    y0 = bnd.min[1] - pad;
  const nx = Math.ceil((bnd.max[0] + pad - x0) / step) + 1,
    ny = Math.ceil((bnd.max[1] + pad - y0) / step) + 1;
  const sg = [];
  for (const ring of polys)
    for (let i = 0; i < ring.length; i++) {
      const a = ring[i],
        b = ring[(i + 1) % ring.length];
      sg.push(a[0], a[1], b[0], b[1]);
    }
  const F = new Float32Array(nx * ny);
  for (let j = 0; j < ny; j++) {
    const py = y0 + j * step;
    for (let i = 0; i < nx; i++) {
      const px = x0 + i * step;
      let best = 1e18,
        inside = false;
      for (let s = 0; s < sg.length; s += 4) {
        const ax = sg[s],
          ay = sg[s + 1],
          bx = sg[s + 2],
          by = sg[s + 3];
        if ((ay > py) !== (by > py) && px < (bx - ax) * (py - ay) / (by - ay) + ax) inside = !inside;
        const dx = bx - ax,
          dy = by - ay;
        let t = ((px - ax) * dx + (py - ay) * dy) / (dx * dx + dy * dy || 1);
        t = t < 0 ? 0 : t > 1 ? 1 : t;
        const ex = ax + t * dx - px,
          ey = ay + t * dy - py,
          d = ex * ex + ey * ey;
        if (d < best) best = d;
      }
      F[j * nx + i] = inside ? -Math.sqrt(best) : Math.sqrt(best);
    }
  }
  return (x, y) => {
    const fx = (x - x0) / step,
      fy = (y - y0) / step;
    if (fx < 0 || fy < 0 || fx >= nx - 1 || fy >= ny - 1) return 20;
    const i = Math.floor(fx),
      j = Math.floor(fy),
      u = fx - i,
      v = fy - j,
      k = j * nx + i;
    return F[k] * (1 - u) * (1 - v) + F[k + 1] * u * (1 - v) + F[k + nx] * (1 - u) * v + F[k + nx + 1] * u * v;
