];
const bowPx = (prm.armBow - 1) * 10,
  prof = [0, 0.3, 0.7, 1, 0.85, 0.45, 0.1, 0];
const armPts = [
    [170, 592, 56],
    [164, 558, 44],
    [156, 522, 34],
    [151, 487, 28],
    [151, 452, 25],
    [155, 418, 23],
    [161, 388, 23],
    [166, 362, 23]
  ]
  .map((p, i) => [p[0] - bowPx * prof[i], p[1], p[2]]);
const armLower = stroke(crSample(armPts));
const Cc = [152 - bowPx * 0.1, 350],
  curl = [];
for (let k = 0; k <= 48; k++) {
  const t = k / 48,
    ph = t * 1.25 * 2 * Math.PI,
    r = 14 - 9 * t,
    w = 23 - 14 * t;
  curl.push([Cc[0] + r * Math.cos(ph), Cc[1] - r * Math.sin(ph), w]);
}
const outline = smooth(bodyPts, 4).add(armLower).offset(2.5, 'Round').offset(-2.5, 'Round')
  .add(stroke([
    [166, 362, 23], ...curl
  ])).add(CrossSection.circle(4 * S, 32).translate(P(Cc))).simplify(0.03);

// ================= BODY SOLID (flat back, rounded top) =================
const d2 = distField(outline, 0.34, 2);
const bodySDF = (p) => {
  const d = d2(p[0], p[1]),
    wx = d + R,
    wy = p[2] - (T - R);
  let s = Math.min(Math.max(wx, wy), 0) + Math.hypot(Math.max(wx, 0), Math.max(wy, 0)) - R;
  s = Math.max(s, -p[2]);
  s = Math.max(s, (d + CH - 0.577 * p[2]) / 1.1547);
  return -s;
};
const ob = outline.bounds();
let body = Manifold.levelSet(bodySDF, { min: [ob.min[0] - 1, ob.min[1] - 1, -0.6], max: [ob.max[0] + 1, ob.max[1] + 1, T + 0.6] }, 0.48);
const bb = api.bbox(body),
  BT = T;
const cutTop = (cs, depth) => cs.extrude(depth + 4).translate([0, 0, BT - depth]);
body = body.subtract(cutTop(spiral(P(Cc), 6.3, 1.3, 1.2, 0.8, 255 / DEG, 1), 1.3));
body = body.add(Manifold.sphere(1.5).scale([1, 1, 0.45]).translate([...P(Cc), BT - 0.1]));
const jackC = P([289, 680]);

function spiralVar(c, r0, r1, turns, w0, w1, start, dir) {
  const n = 220,
    o = [],
    inn = [];
  for (let i = 0; i <= n; i++) {
    const t = i / n,
      a = start + dir * t * turns * 2 * Math.PI,
      r = r0 + (r1 - r0) * t,
      w = w0 + (w1 - w0) * t;
    o.push([c[0] + (r + w / 2) * Math.cos(a), c[1] + (r + w / 2) * Math.sin(a)]);
    inn.push([c[0] + (r - w / 2) * Math.cos(a), c[1] + (r - w / 2) * Math.sin(a)]);
  }
  return toCS(o.concat(inn.reverse()));
}
const swirlTurns = 1.4,
  swirlEnd = -30 / DEG;
const swirlLayers = [
  [1.0, 0.25],
  [0.75, 0.5],
  [0.5, 0.75]
].map(([k, depth]) =>
  cutTop(spiralVar(jackC, 3.6, 7.2, swirlTurns, 0.5 * k, 0.9 * k, swirlEnd - swirlTurns * 2 * Math.PI, 1), depth));
body = body.subtract(Manifold.union(swirlLayers));

// ================= NECK: real profile (flat fretboard, rounded back), raised above the body back =================
const NT = BT + 2.6,
  FB = 1.4;
const yNut = P([0, 190])[1],
  ySad = P([0, 634])[1],
  Lsc = yNut - ySad,
  yFbEnd = P([0, 533])[1],
  yEdge = P([0, 510])[1];
const wAt = (y) => (30 + 10 * (yNut - y) / (yNut - yFbEnd)) * S;
const depthAt = (y) => 5.0 + 0.8 * (yNut - y) / (yNut - yFbEnd);
const fretY = (n) => yNut - Lsc * (1 - Math.pow(2, -n / 12));

function neckProfile(w, D, backOnly = false) {
  const a = w / 2,
    b = D - FB,
    zc = NT - FB,
    pts = backOnly ? [
      [a, zc]
    ] : [
      [-a, NT],
      [a, NT],
      [a, zc]
    ];
  for (let i = 1; i < 32; i++) {
    const t = i / 32 * Math.PI;
    pts.push([a * Math.cos(t), zc - b * Math.sin(t)]);
  }
  pts.push([-a, zc]);
  return toCS(pts);
}
const slab = (cs, y) => cs.extrude(0.05).rotate([90, 0, 0]).translate([0, y + 0.025, 0]);
let neckAll = Manifold.hull([slab(neckProfile(wAt(yNut), depthAt(yNut)), yNut + 1), slab(neckProfile(wAt(yFbEnd), depthAt(yFbEnd)), yFbEnd)]);
const yH = yEdge + 14;
neckAll = neckAll.add(Manifold.hull([
  slab(neckProfile(wAt(yH), depthAt(yH)), yH),
  rrect(wAt(yEdge) + 9, 4, 1.8).extrude(BT + 0.3).translate([0, yEdge - 4, 0]),
]));

// ---- headstock: swan-neck blend + tilted plate ----
const HA = -prm.headTilt,
  ha = HA / DEG;
const Ltr = 10; // length of the blend from neck into headstock
const HS_T = depthAt(yNut) - FB; // headstock thickness = neck-core depth, so the back flows straight through
const sstep = (t) => t * t * (3 - 2 * t);
const NST = 12,
  trPath = [{ y: yNut + 1, z: NT - FB, th: 0 }];
{
  let y = yNut + 1,
    z = NT - FB,
    thPrev = 0;
  for (let i = 1; i <= NST; i++) {
    const th = HA * sstep(i / NST),
      thr = (thPrev + th) / 2 / DEG,
      ds = Ltr / NST;
    y += ds * Math.cos(thr);
    z += ds * Math.sin(thr);
    trPath.push({ y, z, th });
    thPrev = th;
  }
}
const yEnd = trPath[NST].y,
  zEnd = trPath[NST].z;
const hsXf = (m) => m.translate([0, -Ltr, 0]).rotate([HA, 0, 0]).translate([0, yEnd, zEnd]); // local head coords (y' from the nut) -> world
const hsPt = (q) => { const yy = q[1] - Ltr; return [q[0], yy * Math.cos(ha) - q[2] * Math.sin(ha) + yEnd, yy * Math.sin(ha) + q[2] * Math.cos(ha) + zEnd]; };
const headPts = [
  [211, 196],
  [207, 165],
  [203, 130],
  [201, 95],
  [200, 65],
  [198, 42],
  [197, 30],
  [206, 33],
  [216, 42],
  [224, 50],
  [232, 44],
  [240, 34],
  [250, 33],
  [257, 42],
  [257, 56],
  [253, 80],
  [250, 120],
  [247, 160],
  [243, 196]
];
let head = smooth(headPts, 2, PL).extrude(HS_T).translate([0, 0, -HS_T]).intersect(Manifold.cube([60, 100, 40]).translate([-30, Ltr, -20]));
head = head.subtract(CrossSection.circle(1.6).subtract(CrossSection.circle(1.2)).translate(PL([246, 52])).extrude(1).translate([0, 0, -0.35]));
// swan-neck blend: width flares in an S-curve, the rounded back flattens into the plate, the tilt eases in along an arc
const headW = (() => { const b = smooth(headPts, 2, PL).intersect(CrossSection.square([100, 0.2]).translate([-50, Ltr - 0.1])).bounds(); return b.max[0] - b.min[0]; })();

function trProfile(w, n) {
  const a = w / 2,
    pts = [
      [-a, 0]
    ],
    M = 28;
  for (let i = 0; i < M; i++) {
    const ph = i / M * Math.PI,
      c = Math.cos(ph),
      s = Math.sin(ph);
    pts.push([a * Math.sign(c) * Math.pow(Math.abs(c), 2 / n), -HS_T * Math.pow(s, 2 / n)]);
  }
  return toCS(pts);
}
const trSlabs = trPath.map((p, i) => { const t = i / NST; return slab(trProfile(wAt(yNut) + (headW - wAt(yNut)) * sstep(t), 2 + 6 * sstep(t)), 0).rotate([p.th, 0, 0]).translate([0, p.y, p.z]); });
const volute = Manifold.union(trSlabs.slice(0, -1).map((s, i) => Manifold.hull([s, trSlabs[i + 1]])));
add(neckAll.add(hsXf(head)).add(volute), 'neck', COL.neck);

// frets, Love Symbol inlays, nut, truss-rod cover
const frets = [];
for (let n = 1; n <= 22; n++) {
  const y = fretY(n),
    w = wAt(y) - 0.2;
  frets.push(Manifold.cylinder(w, 0.36, 0.36, 16).rotate([0, 90, 0]).translate([-w / 2, y, NT]));
}
add(Manifold.union(frets), 'frets', COL.fret);
const loveCS = (() => {
  const ring = CrossSection.circle(0.75, 48).subtract(CrossSection.circle(0.3, 48));
  const stem = CrossSection.square([2.2, 0.45]).translate([0.6, -0.225]);
  const bar = CrossSection.square([0.45, 1.1]).translate([1.35 - 0.225, -0.55]);
  const arrow = toCS([
    [2.2, -0.62],
    [3.25, 0],
    [2.2, 0.62]
  ]);
  return ring.add(stem).add(bar).add(arrow).translate([-1.25, 0]);
})();
const loveSolid = loveCS.extrude(0.55).translate([0, 0, NT - 0.4]);
const hearts = [];
for (const n of [3, 5, 7, 9, 12, 15, 17, 19, 21]) { const y = (fretY(n) + fretY(n - 1)) / 2; for (const dy of (n === 12 ? [-1.05, 1.05] : [0])) hearts.push(loveSolid.translate([0, y + dy, 0])); }
add(Manifold.union(hearts), 'inlays', COL.inlay);
add(Manifold.cube([wAt(yNut), 1.0, FB + 0.8]).translate([-wAt(yNut) / 2, yNut, NT - FB]), 'nut', COL.nut);
const trc = smooth([
  [227, 150],
  [233, 168],
  [232, 186],
  [222, 186],
  [221, 168]
], 2, PL);
add(hsXf(trc.translate([0, Ltr]).extrude(0.45).translate([0, 0, -0.1])), 'trussCover', COL.black);

// ---- tuners ----
const tun = [],
  posts = {};
for (const py of [80, 104, 128])
  for (const side of [-1, 1]) {
    const xp = 5.3 * side,
      yp = PL([0, py])[1],
      bx = 12.6 * side;
    posts[side + ':' + py] = [xp, yp];
    tun.push(Manifold.cylinder(0.5, 1.35, 1.35, 6).translate([xp, yp, -0.1]));
    tun.push(Manifold.cylinder(HS_T + 3.3, 0.72, 0.72).translate([xp, yp, -HS_T]));
    tun.push(Manifold.cylinder(0.25, 0.72, 0.55).translate([xp, yp, 3.3]));
    tun.push(Manifold.cylinder(1.6, 1.7, 1.7).translate([xp, yp, -HS_T - 1.5]));
    tun.push(Manifold.cylinder(Math.abs(bx - xp), 0.45, 0.45).rotate([0, 90, 0]).translate([Math.min(xp, bx), yp, -HS_T - 0.75]));
    tun.push(Manifold.cylinder(0.9, 1.7, 1.7).rotate([0, 90, 0]).scale([1, 1.25, 1]).translate([bx - 0.45, yp, -HS_T - 0.75]));
  }
add(hsXf(Manifold.union(tun)), 'tuners', COL.gold);

// ================= PICKUPS =================
const screwHead = (r, base) => Manifold.cylinder(base, r, r).add(Manifold.sphere(r).scale([1, 1, 0.45]).translate([0, 0, base]));
const npC = [0, P([0, 550])[1]],
  saCS = rrect(16.6, 4.3, 1.0);
body = body.subtract(cutTop(saCS.offset(0.28, 'Round').translate(npC), 1.6));
add(domed(saCS, BT - 1.6, BT + 1.0, 0.65, 8).translate([npC[0], npC[1], 0]), 'neckPickup', COL.cover);
const saScrews = [];
for (const sx of [-1, 1]) saScrews.push(screwHead(0.6, 0.2).translate([npC[0] + sx * 6.9, npC[1], BT + 0.9]));
add(Manifold.union(saScrews), 'pickupScrews', COL.gold);
if (prm.logos) add(api.text('EMG', { size: 1.0, height: 0.3, font: 'bold', center: true }).translate([npC[0] + 3.6, npC[1], BT + 0.9]), 'logoSA', COL.logo);

const hbC = [0, P([0, 612])[1]];
const ringOuter = rrect(21, 10.8, 1.6),
  ringOpen = rrect(17.0, 9.2, 1.0);
body = body.subtract(cutTop(ringOpen.translate(hbC), 1.6));
const ring = Manifold.hull([ringOuter.extrude(0.05).translate([0, 0, BT - 0.3]), ringOuter.offset(-0.45, 'Round').extrude(0.05).translate([0, 0, BT + 0.8])])
  .subtract(ringOpen.extrude(5).translate([0, 0, BT - 2]));
const rScrews = [];
for (const sx of [-1, 1])
  for (const sy of [-1, 1]) rScrews.push(screwHead(0.6, 0.3).translate([sx * 9.3, sy * 4.05, BT + 0.6]));
add(ring.add(Manifold.union(rScrews)).translate([hbC[0], hbC[1], 0]), 'pickupRing', COL.gold);
add(domed(rrect(16.7, 8.9, 0.9), BT - 1.6, BT + 2.1, 0.55, 8).translate([hbC[0], hbC[1], 0]), 'humbucker', COL.cover);
if (prm.logos) add(api.text('EMG', { size: 1.3, height: 0.3, font: 'bold', center: true }).translate([hbC[0] + 5.2, hbC[1] - 2.6, BT + 2.0]), 'logoHB', COL.logo);

// ================= BRIDGE + TAILPIECE =================
const off = [-0.8, -0.6, -0.4, -0.55, -0.3, -0.1];
const xNut = (i) => -3.9 + i * 1.56,
  xSad = (i) => -5.25 + i * 2.1,
  xTail = (i) => -5.0 + i * 2.0;
const SZ = NT + 1.55,
  yBr = ySad - 0.35,
  yTail = P([0, 655])[1];
const wheelCS = (() => {
  const N = 24,
    pts = [];
  for (let i = 0; i < N; i++) {
    const a = i * 2 * Math.PI / N,
      d = 2 * Math.PI / N;
    pts.push([1.5 * Math.cos(a), 1.5 * Math.sin(a)], [1.38 * Math.cos(a + 0.5 * d), 1.38 * Math.sin(a + 0.5 * d)]);
  }
  return toCS(pts);
})();
const br = [];
for (const sx of [-1, 1]) {
  br.push(Manifold.cylinder(3.3, 0.6, 0.6).translate([sx * 9.9, yBr, BT - 0.3]));
  br.push(wheelCS.extrude(1.4).translate([sx * 9.9, yBr, BT + 0.5]));
}
br.push(domed(rrect(20.6, 2.5, 1.15), BT + 1.9, BT + 3.0, 0.3, 3).translate([0, yBr, 0]));
for (let i = 0; i < 6; i++) {
  const x = xSad(i),
    y = ySad + off[i];
  br.push(Manifold.hull([Manifold.cube([1.75, 1.6, 0.9], true).translate([x, y, BT + 3.15]), Manifold.cube([0.45, 1.6, 0.05], true).translate([x, y, SZ - 0.03])]));
  br.push(Manifold.cylinder(1.3, 0.28, 0.28).rotate([-90, 0, 0]).translate([x, y + 0.6, BT + 3.3]));
  br.push(Manifold.cylinder(0.35, 0.45, 0.45).rotate([-90, 0, 0]).translate([x, yBr + 1.35, BT + 3.3]));
}
for (const sx of [-1, 1]) {
  br.push(Manifold.cylinder(1.9, 1.0, 1.0).translate([sx * 7.4, yTail, BT - 0.3]));
  br.push(Manifold.cylinder(0.4, 1.25, 1.2).translate([sx * 7.4, yTail, BT + 2.35]));
}
br.push(domed(rrect(16.5, 2.6, 1.2), BT + 1.2, BT + 2.7, 0.65, 5).translate([0, yTail, 0]));
add(Manifold.union(br), 'bridge', COL.gold);

// ================= CONTROLS =================
const knobProfile = toCS([
  [0, 0],
  [2.4, 0],
  [2.4, 0.4],
  [2.05, 0.8],
  [1.7, 2.3],
  [1.4, 2.65],
  [0, 2.85]
]);
const fluteCS = (() => {
  const N = 14,
    pts = [];
  for (let i = 0; i < N; i++) {
    const a0 = i * 2 * Math.PI / N,
      d = 2 * Math.PI / N;
    const at = (f, r) => [r * Math.cos(a0 + f * d), r * Math.sin(a0 + f * d)];
    pts.push(at(0, 2.7), at(0.38, 2.7), at(0.42, 1.65), at(0.58, 1.65), at(0.62, 2.7));
  }
  return toCS(pts);
})();
const knobRev = knobProfile.revolve();
const knobSolid = knobRev.intersect(Manifold.cube([10, 10, 0.8]).translate([-5, -5, 0])).add(knobRev.intersect(fluteCS.extrude(4).translate([0, 0, 0.8])));
add(Manifold.union([P([281, 583]), P([284, 610])].map((q) => knobSolid.translate([q[0], q[1], BT - 0.2]))), 'knobs', COL.black);
const gearCS = (() => {
  const N = 12,
    pts = [];
  for (let i = 0; i < N; i++) {
    const a = i * 2 * Math.PI / N,
      d = 2 * Math.PI / N;
    const at = (f, r) => [r * Math.cos(a + f * d), r * Math.sin(a + f * d)];
    pts.push(at(0, 1.5), at(0.12, 1.78), at(0.38, 1.78), at(0.5, 1.5));
  }
  return toCS(pts);
})();
const ctl = [];
const sw = P([287, 652]);
ctl.push(Manifold.cylinder(0.3, 1.4, 1.4).translate([sw[0], sw[1], BT - 0.1]));
ctl.push(gearCS.extrude(0.6).translate([sw[0], sw[1], BT]));
ctl.push(Manifold.cylinder(0.4, 1.3, 0.9).translate([sw[0], sw[1], BT + 0.6]));
ctl.push(Manifold.cylinder(0.9, 0.6, 0.6).translate([sw[0], sw[1], BT + 0.6]));
const tip = [sw[0] + 0.9, sw[1] - 0.3, BT + 4.0];
ctl.push(Manifold.hull([Manifold.sphere(0.55, 24).translate([sw[0], sw[1], BT + 1.3]), Manifold.sphere(0.32, 24).translate(tip)]), Manifold.sphere(0.6, 24).translate(tip));
ctl.push(Manifold.cylinder(0.75, 2.25, 2.25, 6).subtract(Manifold.cylinder(2, 1.3, 1.3).translate([0, 0, -0.5])).translate([jackC[0], jackC[1], BT - 0.1]));

const strapPin = Manifold.union([
  Manifold.cylinder(0.8, 0.6, 0.6).translate([0, 0, -0.5]),
  Manifold.cylinder(0.45, 1.25, 1.25),
  Manifold.cylinder(0.9, 0.7, 0.7).translate([0, 0, 0.4]),
  Manifold.cylinder(0.5, 0.7, 1.35).translate([0, 0, 1.3]),
  Manifold.cylinder(0.7, 1.35, 1.35).translate([0, 0, 1.8]),
  Manifold.sphere(1.35).scale([1, 1, 0.4]).translate([0, 0, 2.5]),
]);
ctl.push(strapPin.rotate([90, 0, 0]).translate([P([225, 0])[0], bb.min[1] + 0.3, 2.9]));
if (prm.hornStrap) ctl.push(strapPin.rotate([180, 0, 0]).translate([19.5, 71.5, 0.3]));
add(Manifold.union(ctl), 'controls', COL.gold);
add(Manifold.cylinder(0.55, 1.36, 1.36).translate([jackC[0], jackC[1], BT - 0.1]), 'jackInsert', COL.black);

add(body, 'body', COL.body);

// ================= STRINGS (optional) =================
if (prm.strings) {
  const postKey = ['-1:80', '-1:104', '-1:128', '1:128', '1:104', '1:80'],
    rad = [0.17, 0.15, 0.13, 0.12, 0.1, 0.09];
  const st = [];
  for (let i = 0; i < 6; i++) {
    const [xp, yp] = posts[postKey[i]];
    const pPost = hsPt([xp - Math.sign(xp) * 0.6, yp, 2.2]);
    const pNut = [xNut(i), yNut + 0.5, NT + 0.75];
    const pSad = [xSad(i), ySad + off[i], SZ + rad[i] - 0.05];
    const pTail = [xTail(i), yTail + 0.9, BT + 2.3];
    st.push(seg(pPost, pNut, rad[i]), seg(pNut, pSad, rad[i]), seg(pSad, pTail, rad[i]));
  }
  add(Manifold.union(st), 'strings', COL.string);
}

return Manifold.union(parts);
